namespace BlazorApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 4;
    private readonly List<Notification> _notifications = new()
    {
        new(1, "Welcome to the app!", DateTime.Now.AddMinutes(-30)),
        new(2, "Your profile was updated.", DateTime.Now.AddMinutes(-15)),
        new(3, "New feature available: Dark mode.", DateTime.Now.AddMinutes(-5)),
    };

    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_notifications)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    public Task<List<Notification>> GetNotificationsSinceAsync(int lastId)
    {
        // Simulate new notifications appearing over time
        lock (_notifications)
        {
            if (Random.Shared.Next(3) == 0) // ~33% chance of a new notification each poll
            {
                var id = _nextId++;
                _notifications.Add(new(id, $"New event #{id} occurred.", DateTime.Now));
            }

            return Task.FromResult(_notifications.Where(n => n.Id > lastId).ToList());
        }
    }
}

